local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
local XLuaUtils = CS.Engine.Lib.XLuaUtils
local BambooQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BambooQuestComponent)
local KTool = CS.Engine.Lib.KTool
local UIFightReardsNode = "Game.UI.FightReady.UIFightReardsNode.UIFightReardsNode"
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"

---@class UIBambooRewardNode          
---@field UIFightReardsNode             	UnityEngine.RectTransform               
---@field TxtState                      	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
---@field TxtReward                     	UnityEngine.RectTransform               
---@field Imgpoint                      	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
local UIBambooRewardNode = Class("UIBambooRewardNode")
function UIBambooRewardNode:__init() 
    self._uiFightReardsNodeScr = nil  
    self._data = nil
    self._cb = nil
end

function UIBambooRewardNode:__delete()
    self._uiFightReardsNodeScr = nil  
    self._data = nil
    self._cb = nil
end

function UIBambooRewardNode:Awake()
    if not self._uiFightReardsNodeScr then
        self._uiFightReardsNodeScr = CfUtils.GetLuaScr(self.UIFightReardsNode, UIFightReardsNode)
    end
end

function UIBambooRewardNode:Start()
end

function UIBambooRewardNode:Refresh(data, cb, activityUuid)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self._activityUuid = checkNumber(activityUuid)

    self:FillSelf()
end

function UIBambooRewardNode:FillSelf()
    self._activityId = BambooUtils.GetActivityId(self._activityUuid)    --活动id
    local vo = BambooUtils.GetBambooActivityVo(self._activityId)
    if vo then
        CfUtils.FillImage(self.ImgIconActivity, vo.rewardTitleIcon)
    end

    local vo = BambooUtils.GetBambooIntegralRewardVo(self._data.id)
    if not vo then
        return
    end

    local isCanDraw = BambooUtils.IsCanDrawReward(self._data.id)
    local isDraw = BambooUtils.IsDrawReward(self._data.id)
    
    CfUtils.SetUISwitchImage(self.ImgBar, isDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgBar2, isDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.Fill, isDraw and 2 or 1)

    local curNum = checkNumber(BambooUtils.GetChallengeCurrencySum())
    CfUtils.FillText(self.Text, localize("<color=#545454><size=30>_num1_</size></color>/_num2_", {_num1_ = curNum, _num2_ = vo.needNum}))
    self.SliderComplete.value = curNum/checkNumber(vo.needNum)

    print(isCanDraw)
    CfUtils.SetActive(self.FontStyleButton, not isDraw and isCanDraw)
    CfUtils.SetActive(self.Complete, isDraw)
    CfUtils.SetActive(self.Underway, not isCanDraw and not isDraw)

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local rewards = RewardConfMgr:GetInstance():_GetRewardData(CfUtils.Split(vo.reward), CfUtils.Split(vo.rewardNum))
        scr:FreshBaseUI(rewards, false)
    end

    if isCanDraw then
        --已领取
        if isDraw then
        else
            SetButtonAction(self.FontStyleButton, Bind(self, self.OnDrawReward))
        end
    else
    end
end

--领取奖励
function UIBambooRewardNode:OnDrawReward()
    if not self._data then
        return
    end

    local isCanDraw = BambooUtils.IsCanDrawReward(self._data.id)
    local isDraw = BambooUtils.IsDrawReward(self._data.id)

    if not isCanDraw then
        GameUtils.Toast(localize("未达成领取条件"))
        return
    elseif isDraw then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    end
    print(self._data.id, self._activityUuid)
    BambooQuestComponent:ActivityQuestPtRewardReq(self._data.id, self._activityUuid, function()
        self:FillSelf()
    end)
end

function UIBambooRewardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBambooRewardNode
